def extract_function_source(code, func_name):
    lines = code.splitlines()
    pattern = re.compile(rf"def\s+{func_name}\s*\(")
    start=None
    for i,l in enumerate(lines):
        if pattern.match(l):
            start=i
            break
    if start is not None:
        # find end by dedent - look for line that has less indent than function initial indent
        indent=len(lines[start])-len(lines[start].lstrip())
        for j in range(start+1,len(lines)):
            if lines[j].strip()=='':
                continue
            current_indent=len(lines[j])-len(lines[j].lstrip())
            if current_indent<=indent and not lines[j].startswith((' ', '\t')): # top-level dedent
                end=j
                break
        else:
            end=len(lines)
        return '\n'.join(lines[start:end])
print(extract_function_source(shepard_code,'execute_module'))

